using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes name of a gift collection. If the collection is owned by a channel chat, then requires can_post_messages administrator right in the channel chat. Returns the changed collection
    /// </summary>
    public Task<TdLib.TdApi.Objects.GiftCollection> SetGiftCollectionNameAsync(MessageSender ownerId = default, int collectionId = default, string name = default)
    {

           using var activity =  StartCallActivity("SetGiftCollectionNameAsync", typeof(SetGiftCollectionName).FullName ?? "SetGiftCollectionNameAsync");

           try
           {
             return client.SetGiftCollectionNameAsync(ownerId, collectionId, name);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
